/**
 * @method
 * @name moveUrl
 * @description 현재 화면을 특정 URL로 이동한다.
 * option.isHistory 지정 시 브라우저 히스토리에 기록되어 뒤로/앞으로 가기로 화면이 복원되고,
 * option.dataInfo 로 현재 화면의 DataCollection JSON 을 넘기면 뒤로가기로 돌아올 때 자동 재설정된다.
 * 복원 진입 화면의 paramData 에는 _isHistoryRestore(true)가 전달되므로, 초기 자동조회 화면은
 * 이를 확인해 조회를 생략해야 복원 데이터가 유지된다.
 * @param {String} moveUrl 화면 파일 경로
 * @param {Object} paramObj 이동 시 전달할 파라미터 값
 * @param {Object} option 이동 옵션 (생략 가능)
 * @param {Boolean} option.isHistory 브라우저 히스토리 기록 여부 (기본값 false)
 * @param {Object} option.dataInfo 복원용 현재 화면 데이터 { 컴포넌트ID : JSON } (isHistory:true 일 때만 사용)
 *  "_" 로 시작하는 키(_pagingInfo 등)는 컴포넌트에 적용하지 않고 paramData 로만 전달되는 예약 키다.
 * @param {Boolean} option.restoreData 이동 대상 화면의 스냅샷이 있으면 복원 이동으로 처리 (기본값 false)
 *  — [목록] 버튼 등 명시적 복귀 이동에 사용. 스냅샷이 없으면 일반 이동으로 동작한다.
 * @hidden N
 * @exception
 * @example
const param = {
    id : "00001",
    name : "홍길동"
};
$c.win.moveUrl("/tmp/tmp01.xml", param);

// [목록 화면] 상세 이동 — 히스토리 기록 + 복원용 스냅샷 (페이징은 _pagingInfo 예약 키)
$c.win.moveUrl("/board/detail.xml", { docId : "00001" }, {
    isHistory : true,
    dataInfo : {
        dma_search : dma_search.getJSON(),
        dlt_list   : dlt_list.getJSON(),
        _pagingInfo : Object.assign({}, scwin.pagingInfo, { totalCnt : scwin.totalCnt })
    }
});

// [상세 화면] 목록 버튼 — 목록 화면을 스냅샷 상태로 복원 이동
$c.win.moveUrl("/board/list.xml", null, { restoreData : true });
 */
scwin.moveUrl = function (moveUrl, paramObj, option) {
    return $c.win.__moveFrameSrc($p.getFrame(), moveUrl, paramObj, option);
};

/**
 * @method
 * @name setPageFrameSrc
 * @description 특정 pageFrame의 웹스퀘어 페이지(XML)을 변경한다.
 * option.isHistory/dataInfo/restoreData 동작은 $c.win.moveUrl 과 동일하다. (뒤로/앞으로 가기 복원, 명시적 복원 이동, 데이터 자동 재설정)
 * @param {Object} pageFrameObj pageFrame 객체
 * @param {String} moveUrl 웹스퀘어 페이지(XML) 파일 경로
 * @param {Object} paramObj pageFrame을 set할 시 전달할 파라미터 객체
 * @param {Object} option 이동 옵션 (생략 가능)
 * @param {Boolean} option.isHistory 브라우저 히스토리 기록 여부 (기본값 false)
 * @param {Object} option.dataInfo 복원용 현재 화면 데이터 { 컴포넌트ID : JSON } (isHistory:true 일 때만 사용)
 * @param {Boolean} option.restoreData 이동 대상 화면의 스냅샷이 있으면 복원 이동으로 처리 (기본값 false)
 * @hidden N
 * @exception
 * @example
const param = {
    id : "00001",
    name : "홍길동"
};
$c.win.setPageFrameSrc(pfm_content, "/tmp/tmp01.xml", param);

// 히스토리 기록 + 뒤로가기 시 현재 화면 데이터 자동 복원
$c.win.setPageFrameSrc(pfm_content, "/tmp/tmp02.xml", param, {
    isHistory : true,
    dataInfo : { dma_search : dma_search.getJSON() }
});
 */
scwin.setPageFrameSrc = function (pageFrameObj, moveUrl, paramObj, option) {
    return $c.win.__moveFrameSrc(pageFrameObj, moveUrl, paramObj, option);
};

/**
 * @method
 * @name __moveFrameSrc
 * @description moveUrl/setPageFrameSrc 공통 구현. isHistory 옵션 처리(떠나는 화면 entry 보강 → setSrc →
 *  새 화면 entry push) 후 프레임 setSrc 결과를 반환한다.
 * @param {Object} frameObj 이동할 pageFrame 객체
 * @param {String} moveUrl 화면 파일 경로
 * @param {Object} paramObj 전달 파라미터
 * @param {Object} option 이동 옵션 ({ isHistory, dataInfo })
 * @hidden Y
 * @exception
 */
scwin.__moveFrameSrc = function (frameObj, moveUrl, paramObj, option) {
    const isHistory = !$c.util.isEmpty(option) && option.isHistory === true;
    const isRestore = !$c.util.isEmpty(option) && option.restoreData === true;
    if (isHistory) {
        // 떠나는 화면의 history entry 에 복원 정보(프레임·데이터 스냅샷)를 병합해 둔다.
        // 뒤로가기로 이 화면에 돌아올 때 popstate 가 전달하는 entry 가 바로 이것이다.
        $c.win.__stampFrameState(frameObj, option.dataInfo);
    }

    // restoreData: 이동 대상 화면의 스냅샷이 레지스트리에 있으면 복원 이동으로 처리한다. (없으면 일반 이동)
    let restoreSnap = null;
    if (isRestore) {
        const frameId = (typeof frameObj.getFrameId === "function") ? frameObj.getFrameId() : frameObj.id;
        restoreSnap = scwin.FRAME_RESTORE_SNAPSHOTS[frameId + "|" + $c.win.__normalizeFrameSrc(moveUrl)] || null;
    }

    // 복원 이동이면 스냅샷의 entry 데이터를 paramData 로 전달한다. (popstate 복원과 동일 계약 —
    // _isHistoryRestore / dataInfo 를 화면이 읽을 수 있다. 명시적 paramObj 가 있으면 그 값이 우선)
    let paramData = paramObj;
    if (restoreSnap) {
        paramData = Object.assign({ "_isHistoryRestore": true }, restoreSnap.stateData, $c.util.isEmpty(paramObj) ? {} : paramObj);
    }

    const setSrcParam = {
        "dataObject": {
            "type": "json",
            "name": "paramData",
            "data": paramData
        }
    };
    const result = frameObj.setSrc($c.sbm.getContextPath() + moveUrl, setSrcParam);

    if (!isHistory && !restoreSnap) {
        return result;
    }

    // 이동 완료 후: 복원 이동이면 dataInfo 자동 적용, 히스토리 이동이면 새 화면 entry push
    const afterMove = function (ok) {
        if (ok === false) {
            return ok;
        }
        if (restoreSnap) {
            scwin.__applyRestoreData(frameObj, restoreSnap.stateData.dataInfo);
        }
        if (isHistory) {
            $c.win.__pushFrameState(frameObj, paramObj);
        }
        return ok;
    };
    if (result && typeof result.then === "function") {
        return result.then(afterMove);
    }
    afterMove(result);
    return result;
};

/**
 * @method
 * @name __normalizeFrameSrc
 * @description 프레임 src 경로를 스냅샷 레지스트리 키 매칭용으로 정규화한다.
 *  (쿼리스트링·contextPath 접두 제거, 선행 슬래시 보정)
 * @param {String} src 프레임 src 또는 이동 URL
 * @returns {String} 정규화된 경로
 * @hidden Y
 * @exception
 */
scwin.__normalizeFrameSrc = function (src) {
    try {
        if ($c.util.isEmpty(src)) {
            return "";
        }
        let path = String(src);
        const queryIdx = path.indexOf("?");
        if (queryIdx > -1) {
            path = path.substring(0, queryIdx);
        }
        const contextPath = $c.sbm.getContextPath();
        if (!$c.util.isEmpty(contextPath) && path.indexOf(contextPath) === 0) {
            path = path.substring(contextPath.length);
        }
        if (path.indexOf("/") !== 0) {
            path = "/" + path;
        }
        return path;
    } catch (ex) {
        console.error(ex);
        return String(src);
    }
};

/**
 * @method
 * @name __stampFrameState
 * @description 떠나는 화면의 history entry(현재 entry)에 프레임 정보와 데이터 스냅샷을 replaceState 로 병합한다.
 * @param {Object} frameObj 현재 pageFrame 객체
 * @param {Object} dataInfo 복원용 데이터 { 컴포넌트ID : JSON } (생략 가능)
 * @hidden Y
 * @exception
 */
scwin.__stampFrameState = function (frameObj, dataInfo) {
    try {
        const curData = (history.state && history.state.data) ? history.state.data : {};
        curData.frameInfo = {
            frameId: (typeof frameObj.getFrameId === "function") ? frameObj.getFrameId() : frameObj.id,
            src: (typeof frameObj.getSrc === "function") ? frameObj.getSrc() : ""
        };
        // 스냅샷은 이번 이동 시점 상태만 유지한다. (이전 이동에서 남은 dataInfo 가 복원되지 않도록 항상 초기화)
        delete curData.dataInfo;
        if (!$c.util.isEmpty(dataInfo)) {
            const cleanInfo = $c.win.__sanitizeStateData(dataInfo);
            if (cleanInfo !== null) {
                curData.dataInfo = cleanInfo;
            }
        }
        history.replaceState({ "data": curData }, "");

        // 명시적 이동 복원(option.restoreData)용으로 동일 스냅샷을 레지스트리에도 저장한다.
        const stateData = $c.win.__sanitizeStateData(curData);
        if (stateData !== null) {
            const snapKey = curData.frameInfo.frameId + "|" + $c.win.__normalizeFrameSrc(curData.frameInfo.src);
            scwin.FRAME_RESTORE_SNAPSHOTS[snapKey] = { stateData: stateData, stampedAt: new Date().getTime() };
        }
    } catch (ex) {
        console.error(ex);
    }
};

/**
 * @method
 * @name __pushFrameState
 * @description 프레임 이동 완료 후 새 화면의 history entry 를 push 한다. (URL 은 pushState 와 동일하게 contextPath)
 * @param {Object} frameObj 이동한 pageFrame 객체
 * @param {Object} paramObj 새 화면에 전달한 파라미터 (앞으로 가기 복원 시 재전달)
 * @hidden Y
 * @exception
 */
scwin.__pushFrameState = function (frameObj, paramObj) {
    try {
        const data = ($c.util.isEmpty(paramObj) ? {} : $c.win.__sanitizeStateData(paramObj)) || {};
        data.frameInfo = {
            frameId: (typeof frameObj.getFrameId === "function") ? frameObj.getFrameId() : frameObj.id,
            src: (typeof frameObj.getSrc === "function") ? frameObj.getSrc() : ""
        };
        history.pushState({ "data": data }, "", $c.sbm.getContextPath().replace(/\/$/, ""));
    } catch (ex) {
        console.error(ex);
    }
};

/**
 * @method
 * @name __sanitizeStateData
 * @description history state 저장용으로 데이터를 정제한다. (함수 등 비직렬화 값 제거, 최대 크기 검사)
 * @param {Object} obj 정제할 객체
 * @returns {Object} JSON 라운드트립을 거친 객체. 직렬화 불가·크기 초과 시 null
 * @hidden Y
 * @exception
 */
scwin.__sanitizeStateData = function (obj) {
    try {
        const str = JSON.stringify(obj);
        if (typeof str !== "string") {
            return null;
        }
        if (str.length > scwin.HISTORY_STATE_MAX_LENGTH) {
            console.warn("[$c.win] history state 데이터가 최대 크기(" + scwin.HISTORY_STATE_MAX_LENGTH + "자)를 초과하여 기록에서 제외합니다.");
            return null;
        }
        return JSON.parse(str);
    } catch (ex) {
        console.error(ex);
        return null;
    }
};

/**
 * @method
 * @name __restoreFrameState
 * @description popstate 로 전달된 프레임 이동 entry 를 복원한다. 프레임을 기록된 화면으로 되돌리고,
 *  setSrc 완료 후 dataInfo 를 화면 DataCollection 에 자동 적용한다.
 * @param {Object} data history.state.data ({ frameInfo, dataInfo?, ... })
 * @returns {Boolean} 복원 착수 여부 (프레임 미발견 시 false — menuInfo 폴백 대상)
 * @hidden Y
 * @exception
 */
scwin.__restoreFrameState = function (data) {
    try {
        const frameObj = $c.util.getComponent(data.frameInfo.frameId);
        if ($c.util.isEmpty(frameObj) || typeof frameObj.setSrc !== "function") {
            console.warn("[$c.win.__restoreFrameState] 복원할 pageFrame(" + data.frameInfo.frameId + ")을 찾을 수 없습니다.");
            return false;
        }
        const restoreParam = {
            "dataObject": {
                "type": "json",
                "name": "paramData",
                "data": Object.assign({ "_isHistoryRestore": true }, data)
            }
        };
        const result = frameObj.setSrc(data.frameInfo.src, restoreParam);
        if (result && typeof result.then === "function") {
            result.then(function (ok) {
                if (ok !== false) {
                    scwin.__applyRestoreData(frameObj, data.dataInfo);
                }
            });
        } else {
            scwin.__applyRestoreData(frameObj, data.dataInfo);
        }
        return true;
    } catch (ex) {
        console.error(ex);
        return false;
    }
};

/**
 * @method
 * @name __applyRestoreData
 * @description 복원된 화면의 DataCollection(dataMap/dataList)에 스냅샷 JSON 을 적용한다.
 * @param {Object} frameObj 복원된 pageFrame 객체
 * @param {Object} dataInfo { 컴포넌트ID : JSON } (없으면 무시)
 * @hidden Y
 * @exception
 */
scwin.__applyRestoreData = function (frameObj, dataInfo) {
    if ($c.util.isEmpty(dataInfo)) {
        return;
    }
    try {
        const scopeWin = (typeof frameObj.getWindow === "function") ? frameObj.getWindow() : null;
        if ($c.util.isEmpty(scopeWin)) {
            console.warn("[$c.win.__applyRestoreData] 복원 대상 화면 scope 를 찾을 수 없습니다.");
            return;
        }
        for (const compId in dataInfo) {
            if (compId.indexOf("_") === 0) {
                continue; // "_" 로 시작하는 예약 키(_pagingInfo 등)는 컴포넌트 적용 대상이 아니다. (paramData 로만 전달)
            }
            let comp = scopeWin[compId];
            if ($c.util.isEmpty(comp) && scopeWin.$p && typeof scopeWin.$p.getComponentById === "function") {
                comp = scopeWin.$p.getComponentById(compId);
            }
            if (!$c.util.isEmpty(comp) && typeof comp.setJSON === "function") {
                comp.setJSON(dataInfo[compId]);
            } else {
                console.warn("[$c.win.__applyRestoreData] 복원 대상 컴포넌트(" + compId + ")를 찾을 수 없습니다.");
            }
        }
    } catch (ex) {
        console.error(ex);
    }
};

/**
 * @method 
 * @name getFrame
 * @description pageFrame안의 스크립트 영역에서 이 함수를 호출할 경우 자신을 감싼 pageFrame object를 반환한다. 전역스크립트에서 호출 시에는 null을 반환한다.
 * @returns {Object} 객체 자신을 감싼 pageFrame object
 * @hidden N
 * @exception 
 * @example
const frameObj = $c.win.getFrame();
 */
scwin.getFrame = function (scopeApi) {
    try {
        if (typeof (scopeApi) == 'object') {
            return scopeApi.getFrame();
        }
        return $p.getFrame();
    } catch (ex) {
        console.error(ex);
    }
};
/**
 * @method 
 * @name getParent
 * @description 자신의 부모 pageFrame 객체를 찾아 반환한다.
 * browserPopup(별도 브라우저 창) 화면에서는 부모 화면에 접근할 수 없으므로 $c.win.getOpenerScope() 를 사용한다.
 * @returns {Object} 자신을 감싼 pageFrame object의 부모 pageFrame 객체
 * @hidden N
 * @exception 
 * @example
const parentFrame = $c.win.getParent();
const dltObj = parentFrame.dlt_dataList1; // 자기 부모 프레임 내에 있는 dlt_dataList1에 접근
const pScwinObj = parentFrame.scwin; // 자기 부모 프레임에 있는 scwin 객체에 접근
if (!$c.util.isEmpty(pScwinObj){
    pScwinObj.search(); // 부모화면에 있는 scwin.search 함수를 호출
}
 */
scwin.getParent = function () {
    try {
        return $p.parent();
    } catch (ex) {
        console.error(ex);
    }
};

/**
 * @method
 * @name getPopupOpenerScope
 * @description browserPopup 오픈 시 등록된 오프너(호출 화면) scope 정보를 popupId 로 조회한다.
 * 자식 팝업 창이 opener 창의 $c.win 을 경유해 호출하는 연동용 함수다. 업무 화면에서는 $c.win.getOpenerScope() 를 사용한다.
 * @param {String} popupId 팝업 아이디
 * @returns {Object} { scope, scopeP } 오프너 scope 정보 (미등록 시 null)
 * @hidden N
 * @exception
 * @example
const openerInfo = $c.win.getPopupOpenerScope("popup1755500000000_1");
 */
scwin.getPopupOpenerScope = function (popupId) {
    if ($c.util.isEmpty(popupId)) {
        return null;
    }
    return scwin.POPUP_OPENER_SCOPES[popupId] || null;
};

/**
 * @method
 * @name getOpenerScope
 * @description 팝업 화면에서 자신을 연 부모 화면의 scope 를 반환한다. (scwin/컴포넌트 접근 가능)
 * browserPopup(별도 브라우저 창)은 window.opener 와 오프너 등록 정보($c.win.openPopup 이 자동 등록)로,
 * 그 외(pageFramePopup 등)는 pageFrame 계층으로 부모를 찾는다.
 * 부모 창이 닫혔거나 접근 불가(COOP 정책 등)하면 null 을 반환한다.
 * @returns {Object} 부모 화면 scope 객체, 접근 불가 시 null
 * @hidden N
 * @exception
 * @example
const openerScope = $c.win.getOpenerScope();
if (!$c.util.isEmpty(openerScope)) {
    openerScope.scwin.searchList(); // 부모 화면의 scwin.searchList 호출
}
 */
scwin.getOpenerScope = function () {
    try {
        if (window.opener != null) {
            // browserPopup: opener 창의 등록 정보에서 호출 화면 scope 복원
            if (window.opener.closed || $c.util.isEmpty(window.opener.$c) || $c.util.isEmpty(window.opener.$c.win)) {
                console.warn("[$c.win.getOpenerScope] 부모 창에 접근할 수 없습니다. (창 닫힘 또는 COOP 정책)");
                return null;
            }
            const openerInfo = window.opener.$c.win.getPopupOpenerScope($c.win.getPopupId());
            return ($c.util.isEmpty(openerInfo) || $c.util.isEmpty(openerInfo.scope)) ? null : openerInfo.scope;
        }
        // pageFramePopup 등 같은 창 안의 팝업: pageFrame 계층의 부모 scope
        return $p.parent();
    } catch (ex) {
        console.error(ex);
        return null;
    }
};

/**
 * @method
 * @name callOpener
 * @description 팝업 화면에서 부모 화면 scwin 의 함수를 호출하고 반환값을 전달한다. (browserPopup/pageFramePopup 공통)
 * 부모 창 접근 불가 또는 함수 미존재 시 호출하지 않고 undefined 를 반환한다.
 * @param {String} fnName 부모 화면 scwin 의 함수명
 * @param {*} args 함수에 전달할 인자 (가변 인자)
 * @returns {*} 부모 함수의 반환값 (호출 실패 시 undefined)
 * @hidden N
 * @exception
 * @example
$c.win.callOpener("searchList");          // 부모 화면의 scwin.searchList() 호출
$c.win.callOpener("setRowData", rowJSON); // 인자 전달
 */
scwin.callOpener = function (fnName) {
    try {
        const openerScope = $c.win.getOpenerScope();
        if ($c.util.isEmpty(openerScope) || $c.util.isEmpty(openerScope.scwin) || typeof openerScope.scwin[fnName] !== "function") {
            console.warn("[$c.win.callOpener] 부모 화면의 함수를 찾을 수 없습니다. (" + fnName + ")");
            return undefined;
        }
        return openerScope.scwin[fnName].apply(openerScope.scwin, Array.prototype.slice.call(arguments, 1));
    } catch (ex) {
        console.error(ex);
        return undefined;
    }
};

/**
 * @method
 * @name setLangCode
 * @description 언어 코드를 설정한다.
 * @param {String} langCode 언어코드 (한국어 : "ko", 영어 : "en", 중국어 : "zh")
 * @hidden N
 * @exception 
 * @example
$c.win.setLangCode("ko");
$c.win.setLangCode("en");
 */
scwin.setLangCode = function (langCode) {
    WebSquare.cookie.setCookie("system_language", langCode);
};

/**
 * @method 
 * @name getLangCode
 * @description 언어 코드를 반환한다.
 * @returns 언어코드 (한국어 : "ko", 영어 : "en", 중국어 : "zh");
 * @hidden N
 * @exception 
 * @example
$c.win.getLangCode();
 */
scwin.getLangCode = function () {
    return WebSquare.cookie.getCookie("system_language");
};

/**
 * @method
 * @name getCbFunctionManager
 * @description 메세지 알림 콜백 Function 정보 저장을 위한 객체를 불러온다.
 * @param
 * @returns {Object} $c.win에 선언된 CB_FUNCTION_MANAGER 객체를 가져온다
 * @hidden N
 * @exception
 * @example const CB_FUNCTION_MANAGER = $c.win.getCbFunctionManager();
 */
scwin.getCbFunctionManager = function () {
    return scwin.CB_FUNCTION_MANAGER
};

/**
 * @method
 * @name openExternalPage
 * @description 외부시스템 화면을 브라우저 새탭으로 호출하기
 * @param url 새탭 주소 https 또는 https로 시작해야함
 * @param options 새탭 주소 https 또는 https로 시작해야함
 * @hidden N
 * @exception
 * @example $c.win.openExternalPage("https://n-dev-staff.krx.co.kr/internal/report/result/RLDFIL00004/20260630134501487801/RLDFIL00004.pdf");
 */
scwin.openExternalPage = function (url,options = {}) {
    window.open(url,"_blank");
};

/**
 * @method
 * @name openFormSubmit
 * @description 폼(Form) 동적 생성 및 제출 공통함수
 * @param {string} url - 요청할 엔드포인트 URL
 * @hidden N
 * @param {Object} [params={}] - 전송할 key-value 데이터 객체
 * @param {Object} [options={}] - 추가 옵션 (method, target, removeAfterSubmit)
 * @param {string} [options.method='POST'] - HTTP 메소드 ('POST', 'GET')
 * @param {string} [options.target='_self'] - 제출 대상 ('_self', '_blank', 또는 iframe name)
 * @param {boolean} [options.removeAfterSubmit=true] - 제출 후 DOM에서 form 제거 여부
 * @example
 * const url = "/api/listing/applsubmit/elwappl/listing-fee-calc/template-download"; 
 * const params = {};
 * const options = {
 * 	   method : "GET"
 * };
 * $c.win.openFormSubmit(url, params, options);
 */
scwin.openFormSubmit = function(url, params = {}, options = {}) {
	const {
		method = 'POST',
		target = '_self',
		removeAfterSubmit = true
	} = options;

	// 1. Form 엘리먼트 생성 및 속성 설정
	const form = document.createElement('form');
	form.method = method.toUpperCase();
	form.action = url;
	form.target = target;
	form.style.display = 'none';

	// 2. 파라미터 객체를 hidden input으로 변환하여 추가
	Object.entries(params).forEach(([key, value]) => {
		// 배열이나 객체 형태 처리 (문자열 변환)
		const val = typeof value === 'object' ? JSON.stringify(value) : value;

		const input = document.createElement('input');
		input.type = 'hidden';
		input.name = key;
		input.value = val ?? '';
		form.appendChild(input);
	});

	// 3. DOM에 추가 후 제출
	document.body.appendChild(form);
	form.submit();

	// 4. 제출 후 DOM 정리
	if (removeAfterSubmit) {
		// submit 직후 삭제하면 일부 브라우저에서 취소될 수 있어 약간의 지연 후 삭제
		setTimeout(() => {
			form.remove();
		}, 100);
	}
};

